class WalletSettingsView extends ConsumerStatefulWidget {
  const WalletSettingsView({
    super.key,
    required this.walletId,
    required this.coin,
    required this.initialSyncStatus,
    required this.initialNodeStatus,
    this.eventBus,
  });

  static const String routeName = "/walletSettings";

  final String walletId;
  final CryptoCurrency coin;
  final WalletSyncStatus initialSyncStatus;
  final NodeConnectionStatus initialNodeStatus;
  final EventBus? eventBus;

  @override
  ConsumerState<WalletSettingsView> createState() => _WalletSettingsViewState();
}

class _WalletSettingsViewState extends ConsumerState<WalletSettingsView> {
  late final String walletId;
  late final CryptoCurrency coin;

  late final EventBus eventBus;

  late WalletSyncStatus _currentSyncStatus;
  // late NodeConnectionStatus _currentNodeStatus;

  late StreamSubscription<dynamic> _syncStatusSubscription;
  // late StreamSubscription _nodeStatusSubscription;

  late final VoidCallback _walletBackupPressed;

  Future<void> _walletBackupPressedHelper() async {
    // TODO: [prio=med] take wallets that don't have a mnemonic into account

    final wallet = ref.read(pWallets).getWallet(widget.walletId);

    List<String>? mnemonic;
    if (wallet is MnemonicInterface &&
        !(wallet is ViewOnlyOptionInterface &&
            (wallet as ViewOnlyOptionInterface).isViewOnly)) {
      mnemonic = await wallet.getMnemonicAsWords();
    }

    KeyDataInterface? keyData;
    if (wallet is ViewOnlyOptionInterface && wallet.isViewOnly) {
      keyData = await wallet.getViewOnlyWalletData();
    }

    if (mounted) {
      if (keyData != null &&
          wallet is ViewOnlyOptionInterface &&
          wallet.isViewOnly) {
        await Navigator.push(
          context,
          RouteGenerator.getRoute(
            shouldUseMaterialRoute: RouteGenerator.useMaterialPageRoute,
            builder: (_) => LockscreenView(
              routeOnSuccessArguments: (walletId: walletId, keyData: keyData),
              showBackButton: true,
              routeOnSuccess: MobileKeyDataView.routeName,
              biometricsCancelButtonString: "CANCEL",
              biometricsLocalizedReason: "Authenticate to view recovery data",
              biometricsAuthenticationTitle: "View recovery data",
            ),
            settings: const RouteSettings(name: "/viewRecoveryDataLockscreen"),
          ),
        );
      } else {
        await Navigator.push(
          context,
          RouteGenerator.getRoute(
            shouldUseMaterialRoute: RouteGenerator.useMaterialPageRoute,
            builder: (_) => LockscreenView(
              routeOnSuccessArguments: (
                walletId: walletId,
                mnemonic: mnemonic ?? [],
              ),
              showBackButton: true,
              routeOnSuccess: WalletBackupView.routeName,
              biometricsCancelButtonString: "CANCEL",
              biometricsLocalizedReason: "Authenticate to view recovery phrase",
              biometricsAuthenticationTitle: "View recovery phrase",
            ),
            settings: const RouteSettings(name: "/viewRecoverPhraseLockscreen"),
          ),
        );
      }
    }
  }

  @override
  void initState() {
    walletId = widget.walletId;
    coin = widget.coin;

    _currentSyncStatus = widget.initialSyncStatus;
    // _currentNodeStatus = widget.initialNodeStatus;

    eventBus = widget.eventBus != null
        ? widget.eventBus!
        : GlobalEventBus.instance;

    _syncStatusSubscription = eventBus
        .on<WalletSyncStatusChangedEvent>()
        .listen((event) async {
          if (event.walletId == walletId) {
            switch (event.newStatus) {
              case WalletSyncStatus.unableToSync:
                // TODO: Handle this case.
                break;
              case WalletSyncStatus.synced:
                // TODO: Handle this case.
                break;
              case WalletSyncStatus.syncing:
                // TODO: Handle this case.
                break;
            }
            setState(() {
              _currentSyncStatus = event.newStatus;
            });
          }
        });

    _walletBackupPressed = IfNotAlreadyAsync<void>(_walletBackupPressedHelper)
        .execute;

    // _nodeStatusSubscription =
    //     eventBus.on<NodeConnectionStatusChangedEvent>().listen(
    //   (event) async {
    //     if (event.walletId == widget.walletId) {
    //       switch (event.newStatus) {
    //         case NodeConnectionStatus.disconnected:
    //           // TODO: Handle this case.
    //           break;
    //         case NodeConnectionStatus.connected:
    //           // TODO: Handle this case.
    //           break;
    //         case NodeConnectionStatus.connecting:
    //           // TODO: Handle this case.
    //           break;
    //       }
    //       setState(() {
    //         _currentNodeStatus = event.newStatus;
    //       });
    //     }
    //   },
    // );
    super.initState();
  }

  @override
  void dispose() {
    // _nodeStatusSubscription.cancel();
    _syncStatusSubscription.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType");
    final wallet = ref.read(pWallets).getWallet(widget.walletId);

    bool canBackup = true;
    if (wallet is ViewOnlyOptionInterface &&
        wallet.isViewOnly &&
        wallet.viewOnlyType == ViewOnlyWalletType.addressOnly) {
      canBackup = false;
    }

    return Background(
      child: Scaffold(
        backgroundColor: Theme.of(context).extension<StackColors>()!.background,
        appBar: AppBar(
          leading: AppBarBackButton(
            onPressed: () {
              Navigator.of(context).pop();
            },
          ),
          title: Text("Settings", style: STextStyles.navBarTitle(context)),
        ),
        body: _WalletSettingsViewBody(
          children: [
            SettingsListButton(
              iconAssetName: Assets.svg.addressBook,
              iconSize: 16,
              title: "Address book",
              onPressed: () {
                Navigator.of(context)
                    .pushNamed(AddressBookView.routeName, arguments: coin);
              },
            ),
            const SizedBox(height: 8),
            SettingsListButton(
              iconAssetName: Assets.svg.node,
              iconSize: 16,
              title: "Network",
              onPressed: () {
                Navigator.of(context).pushNamed(
                  WalletNetworkSettingsView.routeName,
                  arguments: Tuple3(
                    walletId,
                    _currentSyncStatus,
                    widget.initialNodeStatus,
                  ),
                );
              },
            ),
            if (canBackup) const SizedBox(height: 8),
            if (canBackup)
              Consumer(
                builder: (_, ref, __) {
                  return SettingsListButton(
                    iconAssetName: Assets.svg.lock,
                    iconSize: 16,
                    title: "Wallet backup",
                    onPressed: _walletBackupPressed,
                  );
                },
              ),
            const SizedBox(height: 8),
            SettingsListButton(
              iconAssetName: Assets.svg.downloadFolder,
              title: "Wallet settings",
              iconSize: 16,
              onPressed: () {
                Navigator.of(context).pushNamed(
                  WalletSettingsWalletSettingsView.routeName,
                  arguments: walletId,
                );
              },
            ),
            const SizedBox(height: 8),
            SettingsListButton(
              iconAssetName: Assets.svg.arrowRotate,
              title: "Syncing preferences",
              onPressed: () {
                Navigator.of(context)
                    .pushNamed(SyncingPreferencesView.routeName);
              },
            ),
            // const SizedBox(
            //   height: 8,
            // ),
            // SettingsListButton(
            //   iconAssetName: Assets.svg.ellipsis,
            //   title: "Debug Info",
            //   onPressed: () {
            //     Navigator.of(context)
            //         .pushNamed(DebugView.routeName);
            //   },
            // ),
          ],
        ),
      ),
    );
  }
}

